module example.com/tally

go 1.24
# Tally

Tally is a billing platform for SaaS companies. Each organization (a tenant) keeps its customers, sells them plans, bills
them through subscriptions and invoices, takes payments through the payment gateway, and receives webhooks about what
happened. Its own staff work in the organization as members with roles. Go standard library only.

## Layout

| Package | What it does |
|---|---|
| `internal/store` | Everything Tally knows, in memory, safe for concurrent use. Every object belongs to one organization; methods that take an `orgID` only see that organization's objects. |
| `internal/money` | Currencies and amounts. Amounts are `int64` counts of the currency's minor unit (cents for USD), never floats. |
| `internal/billing` | Invoice arithmetic (`Compute`) and billing periods (`AddInterval`). No state. |
| `internal/payments` | Charges invoices through the payment `Gateway`; `Fake` is the gateway of tests and the demo server. |
| `internal/subscriptions` | Starts, changes, cancels and renews subscriptions (`RenewDue` runs every 30 seconds in the server). |
| `internal/webhooks` | Checks endpoint URLs, records events (`Publish`) and sends deliveries (`RunDue`, every 30 seconds). |
| `internal/mail` | Email goes through a `Sender`; `Outbox` keeps messages (tests, demo server). |
| `internal/jobs` | The background job runner. |
| `internal/reports` | The dashboard's reports. |
| `internal/snapshot` | Saves the store to a JSON file and loads it back, migrating files written by older versions. |
| `internal/auth` | Who a request is and what they may do. |
| `internal/api` | The JSON HTTP API, version 1. |
| `internal/apitest` | Builds a whole service with fakes (clock, gateway, outbox, webhook receivers, DNS) and two organizations, for tests. |
| `cmd/tally` | The server: `go run ./cmd/tally -addr :8080 -data tally.json` (prints a demo API key on first start). |

## API conventions

- Every request under `/v1/` sends an API key: `Authorization: Bearer tly_...`. A key acts as the member who created it, in
  that member's organization, with the member's current role (`owner`, `admin`, `billing`, `member`, `viewer`).
- Bodies are JSON. Errors are `{"error": "<code>", "message": "<for people>"}` with the matching status. Another
  organization's object is answered exactly like one that does not exist: 404 `not_found`.
- Lists are `{"items": [...], "next_cursor": "..."}`, oldest first; `?limit=` (1 to 100, default 20) and `?cursor=` page
  through them. `next_cursor` is absent on the last page.
- Times are RFC 3339 in UTC. Amounts are integers in the currency's minor unit; fields ending in `_formatted` are for people.
- Every response carries an `X-Request-Id` (the caller's, when it sent a sensible one).

## Working on Tally

- Run the tests with `go test ./...`. Use `apitest.New(t)` for anything that goes through the API; move time with
  `e.Clock`, never with sleeps.
- The admin tool and the integration test suite (both kept in other repositories) use the exported identifiers of these
  packages and the HTTP API. Keep existing exported names, signatures and API fields working; adding new ones is fine.
package api

import (
	"errors"
	"fmt"
	"net/http"
	"strings"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/money"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// invoiceView is an invoice as the API shows it: with its totals, a one-line description and its customer.
type invoiceView struct {
	store.Invoice
	billing.Totals
	TotalFormatted string       `json:"total_formatted"`
	Description    string       `json:"description"`
	Customer       *customerRef `json:"customer"`
}

// customerRef is the customer shown on an invoice; null when the customer was deleted.
type customerRef struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

func newInvoiceView(inv store.Invoice, c *store.Customer) invoiceView {
	t := billing.Compute(inv)
	v := invoiceView{Invoice: inv, Totals: t, TotalFormatted: money.Format(t.Total, inv.Currency), Description: describe(inv.Lines)}
	if c != nil {
		v.Customer = &customerRef{ID: c.ID, Name: c.Name, Email: c.Email}
	}
	return v
}

// describe is the invoice's first line, and how many more there are.
func describe(lines []store.Line) string {
	d := lines[0].Description
	if len(lines) > 1 {
		d += fmt.Sprintf(" and %d more", len(lines)-1)
	}
	return d
}

func (s *Server) viewInvoice(inv store.Invoice) invoiceView {
	if c, ok := s.store.Customer(inv.OrgID, inv.CustomerID); ok {
		return newInvoiceView(inv, &c)
	}
	return newInvoiceView(inv, nil)
}

func findCustomer(cs []store.Customer, id string) *store.Customer {
	for i := range cs {
		if cs[i].ID == id {
			return &cs[i]
		}
	}
	return nil
}

func invoiceViewKey(v invoiceView) cursor { return cursor{T: v.CreatedAt, ID: v.ID} }

// listInvoices lists the organization's invoices, oldest first, optionally only those of ?customer_id=, ?subscription_id=
// or with ?status=.
func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	status := store.InvoiceStatus(q.Get("status"))
	if status != "" && status != store.InvoiceOpen && status != store.InvoicePaid && status != store.InvoiceVoid {
		writeError(w, http.StatusBadRequest, "invalid_status", "status is open, paid or void")
		return
	}
	invs := s.store.ListInvoices(p.OrgID, store.InvoiceFilter{CustomerID: q.Get("customer_id"), SubscriptionID: q.Get("subscription_id"), Status: status})
	customers := s.store.Customers(p.OrgID)
	views := make([]invoiceView, 0, len(invs))
	for _, inv := range invs {
		views = append(views, newInvoiceView(inv, findCustomer(customers, inv.CustomerID)))
	}
	items, next := pageOf(views, invoiceViewKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		CustomerID      string         `json:"customer_id"`
		Currency        money.Currency `json:"currency"`
		Lines           []store.Line   `json:"lines"`
		DiscountPercent int            `json:"discount_percent"`
	}
	if !decode(w, r, &in) {
		return
	}
	if len(in.Lines) == 0 {
		writeError(w, http.StatusUnprocessableEntity, "invalid", "an invoice needs at least one line")
		return
	}
	for _, l := range in.Lines {
		if strings.TrimSpace(l.Description) == "" || l.Quantity <= 0 || l.UnitAmount < 0 {
			writeError(w, http.StatusUnprocessableEntity, "invalid", "each line needs a description, a positive quantity and a unit amount that is not negative")
			return
		}
	}
	inv, err := s.store.CreateInvoice(store.Invoice{OrgID: p.OrgID, CustomerID: in.CustomerID, Currency: in.Currency, Lines: in.Lines, DiscountPercent: in.DiscountPercent}, s.clock.Now())
	if err != nil {
		if errors.Is(err, store.ErrCustomerOrgMismatch) {
			writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", fmt.Sprintf("customer %s belongs to another organization", in.CustomerID))
			return
		}
		s.storeError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID})
	writeJSON(w, http.StatusCreated, s.viewInvoice(inv))
}

func (s *Server) getInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	inv, ok := s.store.Invoice(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such invoice")
		return
	}
	writeJSON(w, http.StatusOK, s.viewInvoice(inv))
}

// getInvoiceLines answers an invoice's lines with each line's amount, for the dashboard's invoice table.
func (s *Server) getInvoiceLines(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	inv, ok := s.store.InvoiceByID(r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such invoice")
		return
	}
	type lineView struct {
		store.Line
		Amount int64 `json:"amount"`
	}
	items := []lineView{}
	for _, l := range inv.Lines {
		items = append(items, lineView{Line: l, Amount: l.Amount()})
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

// payInvoice charges an invoice: {"payment_method": "pm_..."}, or the customer's default payment method when it is absent.
func (s *Server) payInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		PaymentMethod string `json:"payment_method"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	inv, pay, err := s.pay.Pay(r.Context(), p.OrgID, r.PathValue("id"), in.PaymentMethod)
	if err != nil {
		s.payError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"invoice": s.viewInvoice(inv), "payment": pay})
}

func (s *Server) payError(w http.ResponseWriter, err error) {
	var decline *payments.DeclineError
	switch {
	case errors.As(err, &decline):
		writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
	case errors.Is(err, payments.ErrAlreadyPaid):
		writeError(w, http.StatusConflict, "already_paid", err.Error())
	case errors.Is(err, payments.ErrInvoiceVoid):
		writeError(w, http.StatusConflict, "invoice_void", err.Error())
	case errors.Is(err, payments.ErrNoPaymentMethod):
		writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
	case errors.Is(err, payments.ErrUnavailable):
		writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
	default:
		s.storeError(w, err)
	}
}

func (s *Server) voidInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	now := s.clock.Now()
	inv, err := s.store.UpdateInvoice(p.OrgID, r.PathValue("id"), func(inv *store.Invoice) error {
		switch inv.Status {
		case store.InvoicePaid:
			return payments.ErrAlreadyPaid
		case store.InvoiceVoid:
			return payments.ErrInvoiceVoid
		}
		inv.Status, inv.VoidedAt = store.InvoiceVoid, &now
		return nil
	})
	if err != nil {
		s.payError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "invoice.voided", map[string]any{"invoice_id": inv.ID})
	writeJSON(w, http.StatusOK, s.viewInvoice(inv))
}

func (s *Server) listPayments(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	writeJSON(w, http.StatusOK, list{Items: s.store.Payments(p.OrgID, r.URL.Query().Get("invoice_id"))})
}
// Package api is Tally's JSON HTTP API (version 1). Every request under /v1/ presents an API key as
// "Authorization: Bearer <token>"; the key acts as the member who created it, in that member's organization, with the
// member's current role. The API only ever shows the caller's organization's data.
package api

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"io"
	"log/slog"
	"net/http"
	"regexp"
	"strings"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
	"example.com/tally/internal/webhooks"
)

// Options configure a Server.
type Options struct {
	Clock         clock.Clock            // nil: clock.Real
	Payments      *payments.Service      // required
	Subscriptions *subscriptions.Service // required
	Webhooks      *webhooks.Service      // nil: a service with the default HTTP client and resolver
	Mail          mail.Sender            // nil: an Outbox (nothing is sent)
	Logger        *slog.Logger           // nil: discard
	// BaseURL is the dashboard's address, for links in emails (default "https://app.tally.example").
	BaseURL string
}

// Server serves the API.
type Server struct {
	store   *store.Store
	clock   clock.Clock
	pay     *payments.Service
	subs    *subscriptions.Service
	hooks   *webhooks.Service
	mail    mail.Sender
	log     *slog.Logger
	baseURL string
	mux     *http.ServeMux
	handler http.Handler
}

// New returns a server over a store.
func New(st *store.Store, opt Options) *Server {
	if opt.Payments == nil || opt.Subscriptions == nil {
		panic("api.New: Options.Payments and Options.Subscriptions are required")
	}
	s := &Server{store: st, clock: opt.Clock, pay: opt.Payments, subs: opt.Subscriptions, hooks: opt.Webhooks, mail: opt.Mail, log: opt.Logger,
		baseURL: strings.TrimRight(opt.BaseURL, "/"), mux: http.NewServeMux()}
	if s.clock == nil {
		s.clock = clock.Real{}
	}
	if s.hooks == nil {
		s.hooks = webhooks.New(webhooks.Options{Store: st, Clock: s.clock})
	}
	if s.mail == nil {
		s.mail = &mail.Outbox{}
	}
	if s.log == nil {
		s.log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	if s.baseURL == "" {
		s.baseURL = "https://app.tally.example"
	}
	s.routes()
	s.handler = s.withRequestID(s.recoverPanics(s.mux))
	return s
}

// ServeHTTP implements http.Handler.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) { s.handler.ServeHTTP(w, r) }

func (s *Server) routes() {
	m := s.mux
	m.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	m.HandleFunc("GET /v1/me", s.authed(s.getMe))

	m.HandleFunc("GET /v1/org", s.authed(s.getOrg))
	m.HandleFunc("PATCH /v1/org", s.authed(s.updateOrg))
	m.HandleFunc("GET /v1/members", s.authed(s.listMembers))
	m.HandleFunc("PATCH /v1/members/{user_id}", s.authed(s.updateMember))
	m.HandleFunc("DELETE /v1/members/{user_id}", s.authed(s.removeMember))
	m.HandleFunc("GET /v1/invites", s.authed(s.listInvites))
	m.HandleFunc("POST /v1/invites", s.authed(s.createInvite))
	m.HandleFunc("DELETE /v1/invites/{id}", s.authed(s.revokeInvite))
	m.HandleFunc("POST /v1/invites/accept", s.acceptInvite) // no API key: the token is the credential
	m.HandleFunc("GET /v1/api-keys", s.authed(s.listAPIKeys))
	m.HandleFunc("POST /v1/api-keys", s.authed(s.createAPIKey))
	m.HandleFunc("DELETE /v1/api-keys/{id}", s.authed(s.revokeAPIKey))

	m.HandleFunc("GET /v1/customers", s.authed(s.listCustomers))
	m.HandleFunc("POST /v1/customers", s.authed(s.createCustomer))
	m.HandleFunc("GET /v1/customers/export.csv", s.authed(s.exportCustomers))
	m.HandleFunc("GET /v1/customers/{id}", s.authed(s.getCustomer))
	m.HandleFunc("PATCH /v1/customers/{id}", s.authed(s.updateCustomer))
	m.HandleFunc("DELETE /v1/customers/{id}", s.authed(s.deleteCustomer))

	m.HandleFunc("GET /v1/plans", s.authed(s.listPlans))
	m.HandleFunc("POST /v1/plans", s.authed(s.createPlan))
	m.HandleFunc("GET /v1/plans/{id}", s.authed(s.getPlan))
	m.HandleFunc("PATCH /v1/plans/{id}", s.authed(s.updatePlan))

	m.HandleFunc("GET /v1/subscriptions", s.authed(s.listSubscriptions))
	m.HandleFunc("POST /v1/subscriptions", s.authed(s.createSubscription))
	m.HandleFunc("GET /v1/subscriptions/{id}", s.authed(s.getSubscription))
	m.HandleFunc("PATCH /v1/subscriptions/{id}", s.authed(s.updateSubscription))
	m.HandleFunc("POST /v1/subscriptions/{id}/cancel", s.authed(s.cancelSubscription))
	m.HandleFunc("POST /v1/subscriptions/{id}/usage", s.authed(s.reportUsage))

	m.HandleFunc("GET /v1/invoices", s.authed(s.listInvoices))
	m.HandleFunc("POST /v1/invoices", s.authed(s.createInvoice))
	m.HandleFunc("GET /v1/invoices/{id}", s.authed(s.getInvoice))
	m.HandleFunc("GET /v1/invoices/{id}/lines", s.authed(s.getInvoiceLines))
	m.HandleFunc("POST /v1/invoices/{id}/pay", s.authed(s.payInvoice))
	m.HandleFunc("POST /v1/invoices/{id}/void", s.authed(s.voidInvoice))
	m.HandleFunc("GET /v1/payments", s.authed(s.listPayments))

	m.HandleFunc("GET /v1/webhook-endpoints", s.authed(s.listEndpoints))
	m.HandleFunc("POST /v1/webhook-endpoints", s.authed(s.createEndpoint))
	m.HandleFunc("GET /v1/webhook-endpoints/{id}", s.authed(s.getEndpoint))
	m.HandleFunc("PATCH /v1/webhook-endpoints/{id}", s.authed(s.updateEndpoint))
	m.HandleFunc("DELETE /v1/webhook-endpoints/{id}", s.authed(s.deleteEndpoint))
	m.HandleFunc("GET /v1/webhook-endpoints/{id}/deliveries", s.authed(s.listDeliveries))
	m.HandleFunc("GET /v1/events", s.authed(s.listEvents))
	m.HandleFunc("GET /v1/events/{id}", s.authed(s.getEvent))

	m.HandleFunc("GET /v1/reports/revenue", s.authed(s.revenueReport))
}

// handler is an endpoint that runs for a known member.
type handler func(w http.ResponseWriter, r *http.Request, p auth.Principal)

// authed resolves the request's API key to the member it acts for, or answers 401. Viewers may only read: any other method
// answers 403.
func (s *Server) authed(h handler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
		if !ok {
			writeError(w, http.StatusUnauthorized, "unauthorized", "send an API key as Authorization: Bearer <token>")
			return
		}
		key, ok := s.store.APIKeyByToken(strings.TrimSpace(token))
		if !ok || key.RevokedAt != nil {
			writeError(w, http.StatusUnauthorized, "unauthorized", "unknown or revoked API key")
			return
		}
		m, ok := s.store.Member(key.OrgID, key.UserID)
		if !ok {
			writeError(w, http.StatusUnauthorized, "unauthorized", "the key's owner is no longer a member")
			return
		}
		s.store.TouchAPIKey(key.ID, s.clock.Now())
		p := auth.Principal{OrgID: key.OrgID, UserID: key.UserID, KeyID: key.ID, Role: m.Role}
		if r.Method != http.MethodGet && !auth.CanWrite(p.Role) {
			writeError(w, http.StatusForbidden, "forbidden", "viewers can only read")
			return
		}
		h(w, r, p)
	}
}

type ctxKey int

const requestIDKey ctxKey = 0

var requestIDRe = regexp.MustCompile(`^[A-Za-z0-9._-]{1,128}$`)

// withRequestID gives every request an ID: the caller's X-Request-Id when it is sensible, a new one otherwise. It is sent
// back in the X-Request-Id header.
func (s *Server) withRequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Request-Id")
		if !requestIDRe.MatchString(id) {
			b := make([]byte, 8)
			_, _ = rand.Read(b)
			id = "req_" + hex.EncodeToString(b)
		}
		w.Header().Set("X-Request-Id", id)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), requestIDKey, id)))
	})
}

// RequestID returns the ID of the request ctx belongs to.
func RequestID(ctx context.Context) string {
	id, _ := ctx.Value(requestIDKey).(string)
	return id
}

func (s *Server) recoverPanics(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if v := recover(); v != nil {
				s.log.Error("panic", "method", r.Method, "path", r.URL.Path, "panic", v, "request_id", RequestID(r.Context()))
				writeError(w, http.StatusInternalServerError, "internal", "something went wrong")
			}
		}()
		next.ServeHTTP(w, r)
	})
}

func (s *Server) publish(ctx context.Context, orgID, typ string, data any) {
	if err := s.hooks.Publish(ctx, orgID, typ, data); err != nil {
		s.log.Error("publish event", "type", typ, "err", err)
	}
}
package api

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"time"

	"example.com/tally/internal/store"
)

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// writeError answers {"error": code, "message": message}.
func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]string{"error": code, "message": message})
}

// decode reads a JSON body (at most 1 MiB) into v, or answers 400 and returns false.
func decode(w http.ResponseWriter, r *http.Request, v any) bool {
	dec := json.NewDecoder(io.LimitReader(r.Body, 1<<20))
	if err := dec.Decode(v); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "the body is not valid JSON: "+err.Error())
		return false
	}
	return true
}

// storeError answers for an error from the store or a service.
func (s *Server) storeError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		writeError(w, http.StatusNotFound, "not_found", "no such object")
	case errors.Is(err, store.ErrEmailTaken):
		writeError(w, http.StatusConflict, "email_taken", err.Error())
	case errors.Is(err, store.ErrAlreadyMember):
		writeError(w, http.StatusConflict, "already_member", err.Error())
	case errors.Is(err, store.ErrConflict):
		writeError(w, http.StatusConflict, "conflict", err.Error())
	case errors.Is(err, store.ErrCustomerOrgMismatch):
		writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", err.Error())
	case errors.Is(err, store.ErrInvalid):
		writeError(w, http.StatusUnprocessableEntity, "invalid", err.Error())
	default:
		s.log.Error("request failed", "err", err)
		writeError(w, http.StatusInternalServerError, "internal", "something went wrong")
	}
}

// list is the shape of every list response. NextCursor is set when there is another page.
type list struct {
	Items      any    `json:"items"`
	NextCursor string `json:"next_cursor,omitempty"`
}

// page is a request for one page of a list: ?limit= (1 to 100, default 20) and ?cursor= (from the previous page).
type page struct {
	limit int
	after *cursor
}

// cursor is where a page starts: after the item with this creation time and ID.
type cursor struct {
	T  time.Time `json:"t"`
	ID string    `json:"id"`
}

func (c cursor) less(o cursor) bool {
	if !c.T.Equal(o.T) {
		return c.T.Before(o.T)
	}
	return c.ID < o.ID
}

// parsePage reads ?limit and ?cursor, or answers 400 and returns false.
func parsePage(w http.ResponseWriter, r *http.Request) (page, bool) {
	p := page{limit: 20}
	if v := r.URL.Query().Get("limit"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 || n > 100 {
			writeError(w, http.StatusBadRequest, "invalid_limit", "limit is a whole number from 1 to 100")
			return page{}, false
		}
		p.limit = n
	}
	if v := r.URL.Query().Get("cursor"); v != "" {
		b, err := base64.RawURLEncoding.DecodeString(v)
		var c cursor
		if err != nil || json.Unmarshal(b, &c) != nil || c.ID == "" {
			writeError(w, http.StatusBadRequest, "invalid_cursor", "the cursor is not one this API gave out")
			return page{}, false
		}
		p.after = &c
	}
	return p, true
}

func encodeCursor(c cursor) string {
	b, _ := json.Marshal(c)
	return base64.RawURLEncoding.EncodeToString(b)
}

// pageOf returns one page of items, which are sorted by key (creation time, then ID), and the cursor of the next page.
func pageOf[T any](items []T, key func(T) cursor, p page) ([]T, string) {
	start := 0
	if p.after != nil {
		start = len(items)
		for i, it := range items {
			if p.after.less(key(it)) {
				start = i
				break
			}
		}
	}
	end := min(start+p.limit, len(items))
	out := items[start:end]
	next := ""
	if end < len(items) && len(out) > 0 {
		next = encodeCursor(key(out[len(out)-1]))
	}
	return out, next
}

