// idempotencyKeyRe is what an Idempotency-Key may be: 1 to 255 printable ASCII characters (space included).
var idempotencyKeyRe = regexp.MustCompile(`^[ -~]{1,255}$`)

// payInvoice charges an invoice: {"payment_method": "pm_..."}, or the customer's default payment method when it is absent.
// A request with an Idempotency-Key header is charged at most once per key (see chargeOnce).
func (s *Server) payInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	key := ""
	if keys := r.Header.Values("Idempotency-Key"); len(keys) > 0 {
		if len(keys) > 1 || !idempotencyKeyRe.MatchString(keys[0]) {
			writeError(w, http.StatusBadRequest, "invalid_idempotency_key", "Idempotency-Key is 1 to 255 printable ASCII characters")
			return
		}
		key = keys[0]
	}
	var in struct {
		PaymentMethod string `json:"payment_method"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	if key == "" {
		s.chargeInvoice(w, r, p, r.PathValue("id"), in.PaymentMethod)
		return
	}
	s.chargeOnce(w, r, p, key, r.PathValue("id"), in.PaymentMethod)
}

// chargeOnce charges an invoice for a request that carries an Idempotency-Key. The first request with a key does the work,
// and its answer is kept for store.IdempotencyTTL: a later request with the same key, invoice and payment method gets that
// answer again, marked Idempotent-Replayed, and nothing is charged. The same key with another invoice or payment method is
// refused, and a request with the key that arrives while the first is still being handled is refused at once. An answer of
// 500 or more is not kept, so a retry with the key runs the payment again.
func (s *Server) chargeOnce(w http.ResponseWriter, r *http.Request, p auth.Principal, key, invoiceID, paymentMethod string) {
	fp := paymentFingerprint(invoiceID, paymentMethod)
	held, reserved := s.store.ReserveIdempotencyKey(p.OrgID, key, fp, s.clock.Now())
	if !reserved {
		switch {
		case held.Fingerprint != fp:
			writeError(w, http.StatusUnprocessableEntity, "idempotency_key_reused", "this Idempotency-Key was used for another invoice or payment method")
		case !held.Done:
			writeError(w, http.StatusConflict, "request_in_progress", "a request with this Idempotency-Key is still being handled")
		default:
			w.Header().Set("Content-Type", "application/json")
			w.Header().Set("Idempotent-Replayed", "true")
			w.WriteHeader(held.Status)
			_, _ = w.Write(held.Body)
		}
		return
	}
	kept := false
	defer func() {
		if !kept {
			s.store.ReleaseIdempotencyKey(p.OrgID, key)
		}
	}()
	c := newCapture()
	s.chargeInvoice(c, r, p, invoiceID, paymentMethod)
	if c.status < http.StatusInternalServerError {
		s.store.KeepIdempotencyResponse(p.OrgID, key, c.status, c.body.Bytes(), s.clock.Now())
		kept = true
	}
	for k, v := range c.header {
		w.Header()[k] = v
	}
	w.WriteHeader(c.status)
	_, _ = w.Write(c.body.Bytes())
}

// chargeInvoice pays the invoice and answers with the invoice and the payment.
func (s *Server) chargeInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal, invoiceID, paymentMethod string) {
	inv, pay, err := s.pay.Pay(r.Context(), p.OrgID, invoiceID, paymentMethod)
	if err != nil {
		s.payError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"invoice": s.viewInvoice(inv), "payment": pay})
}

// paymentFingerprint identifies what a pay request asks for: the invoice and the payment method it names.
func paymentFingerprint(invoiceID, paymentMethod string) string {
	sum := sha256.Sum256([]byte(invoiceID + "\x00" + paymentMethod))
	return hex.EncodeToString(sum[:])
}

func (s *Server) payError(w http.ResponseWriter, err error) {
	var decline *payments.DeclineError
	switch {
	case errors.As(err, &decline):
		writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
	case errors.Is(err, payments.ErrAlreadyPaid):
		writeError(w, http.StatusConflict, "already_paid", err.Error())
	case errors.Is(err, payments.ErrInvoiceVoid):
		writeError(w, http.StatusConflict, "invoice_void", err.Error())
	case errors.Is(err, payments.ErrNoPaymentMethod):
		writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
	case errors.Is(err, payments.ErrUnavailable):
		writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
	default:
		s.storeError(w, err)
	}
}

func (s *Server) voidInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	now := s.clock.Now()
	inv, err := s.store.UpdateInvoice(p.OrgID, r.PathValue("id"), func(inv *store.Invoice) error {
		switch inv.Status {
		case store.InvoicePaid:
			return payments.ErrAlreadyPaid
		case store.InvoiceVoid:
			return payments.ErrInvoiceVoid
		}
		inv.Status, inv.VoidedAt = store.InvoiceVoid, &now
		return nil
	})
	if err != nil {
		s.payError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "invoice.voided", map[string]any{"invoice_id": inv.ID})
	writeJSON(w, http.StatusOK, s.viewInvoice(inv))
}

func (s *Server) listPayments(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	writeJSON(w, http.StatusOK, list{Items: s.store.Payments(p.OrgID, r.URL.Query().Get("invoice_id"))})
}

